select count(*) filter(where archived_at is null) active_items,count(*) filter(where archived_at is not null) archived_items,
 count(*) filter(where archived_at is null and stock_status in ('low','out')) active_low_stock_items from public.consumables;
select c.name,c.prefix,c.sort_order,count(i.id) catalog_skus from public.consumable_categories c left join public.consumables i on i.category=c.name and i.archived_at is null and i.catalog_key like 'catalog-20261022:%' group by c.name,c.prefix,c.sort_order order by c.sort_order;
select count(distinct catalog_key) catalog_skus,count(distinct name) source_families from public.consumables where archived_at is null and catalog_key like 'catalog-20261022:%';
select * from public.consumables where current_stock<0 or current_stock>=1000000000;
select item_code,count(*) from public.consumables where item_code is not null group by item_code having count(*)>1;
select id,name,unit,specification from public.consumables where archived_at is null and (category is null or item_code is null);
select c.item_code,c.current_stock,c.minimum_stock,c.stock_status from public.consumables c where archived_at is null and stock_status in ('low','out') order by item_code;
select c.id,c.name,c.current_stock,c.minimum_stock,c.archived_at,c.archive_reason,
 (select count(*) from public.consumable_stock_movements m where m.consumable_id=c.id) preserved_movements
 from public.consumables c where c.archived_at is not null;
select * from public.consumable_archive_events order by created_at,id;
select c.item_code,m.* from public.consumable_stock_movements m join public.consumables c on c.id=m.consumable_id where m.note like 'Catalog import 2026-10-22:%' and (m.quantity_change<>100 or m.balance_after<>100);
